// This tests ECMAScript iteration only. It does not load Thunderbird or Assert.
const observedProperties = {
  CTA: 'cta',
  id: 'data-id',
  description: 'description',
  title: 'heading',
  type: 'type',
  URL: 'url',
};
const actual = [];
for (const [key, value] in observedProperties) {
  actual.push({ key, value });
}
const expected = Object.entries(observedProperties).map(([key, value]) => ({ key, value }));
console.log(JSON.stringify({
  experiment: 'ECMAScript iteration only; no Thunderbird or Assert execution',
  node: process.version,
  actual,
  expected,
}, null, 2));

